import 'package:flutter/material.dart';
import '../models/masonry_input.dart';
import '../models/masonry_result.dart';
import '../models/productivity_standard.dart';
import '../widgets/app_scaffold.dart';
class MasonryV2ResultScreen extends StatelessWidget { final MasonryEstimateResult result; const MasonryV2ResultScreen({super.key,required this.result}); String n(double v,[int d=2])=>v.toStringAsFixed(d); String money(double v)=>'₹${v.toStringAsFixed(0)}';
@override Widget build(BuildContext context){final t=result.takeoff;final l=result.labour;final p=result.productivity;return AppScaffold(title:'Masonry Estimate',bodyBuilder:(context,pad)=>ListView(padding:pad,children:[Text('Masonry Estimate',style:Theme.of(context).textTheme.headlineSmall),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[row('Net Masonry Area','${n(result.area.netArea)} m²'),row(result.input.type.unitLabel,'${t.unitCount}'),row('Mortar','${n(t.mortarVolume)} m³'),row('Material Cost',money(result.materialCost)),row('Labour Cost',money(l.totalCost)),row('Total Cost',money(result.totalCost)),row('Cost / m²',money(result.costPerSquareMetre))]))),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('LABOUR & TIME',style:Theme.of(context).textTheme.titleMedium),row('Crew','${result.input.masons} Mason + ${result.input.helpers} Helper'),row('Working Days','${n(p.workingDays)} days'),row('Labour Cost',money(l.totalCost))]))),Card(child:ExpansionTile(title:const Text('Calculation Details'),childrenPadding:const EdgeInsets.all(16),children:[row('Gross area','${n(result.area.grossArea)} m²'),row('Opening deductions','${n(result.area.deductionArea)} m²'),row('Wall volume','${n(t.masonryVolume)} m³'),row('Unit size',result.input.unitSize.displayLabel),row('Wastage','${n(result.input.wastagePercent)}%'),row('Cement','${n(t.cementBags)} bags'),row('Sand','${n(t.sandM3)} m³'),row('Mason mandays',n(p.mandays[LabourRole.mason]??0)),row('Helper mandays',n(p.mandays[LabourRole.helper]??0)),row('Reference note','Reference values are editable; verify locally.')]))]));}
Widget row(String a,String b)=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Text(a)),Text(b)]));}
